#include <vector>
#include <unordered_set>

class Solution {
public:
    std::vector<int> getSneakyNumbers(std::vector<int>& nums) {
        std::unordered_set<int> seen;
        std::vector<int> res;
        for (int x : nums) {
            if (seen.count(x)) res.push_back(x);
            else seen.insert(x);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] getSneakyNumbers(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        int[] res = new int[2];
        int idx = 0;
        for (int x : nums) {
            if (seen.contains(x)) {
                res[idx++] = x;
            } else {
                seen.add(x);
            }
        }
        return res;
    }
}

var getSneakyNumbers = function(nums) {
    const seen = new Set();
    const res = [];
    for (const x of nums) {
        if (seen.has(x)) {
            res.push(x);
        } else {
            seen.add(x);
        }
    }
    return res;
};
